 function latestSettings(rs){const out={};for(const r of rs.filter(r=>!r.voided&&r.marker==='settings').slice().sort((a,b)=>Date.parse(a.observedAt)-Date.parse(b.observedAt)||a.revision-b.revision)){if(r.settings?.agent!=null)out.agent={text:settingsText({agent:r.settings.agent,concentration:r.settings.concentration}),at:r.observedAt};if(r.settings?.ventilation)out.ventilation={text:ventilationNames[r.settings.ventilation],at:r.observedAt};if(r.settings?.oxygen)out.oxygen={text:r.settings.oxygen,at:r.observedAt};}return out;}
